import { Controller, Delete, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 메시지 첨부파일은 attachment.owner_type = 'MESSAGE', owner_id = message_id 로 연결된다.
const MESSAGE_OWNER_TYPE = 'MESSAGE';
const MESSAGE_TYPES = ['NOTE', 'CHAT', 'MAIL'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

@Controller('api/v1')
export class FnSfr03603Controller {
  @Delete('/notifications/:notificationId')
  @HttpCode(200)
  async deleteNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const notificationId = req.params['notificationId'];
    if (!/^[0-9]+$/.test(notificationId)) {
      throw new ApiError(404, 'NOTIFICATION_NOT_FOUND', '알림을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT title AS "title"
           FROM notification
          WHERE notification_id = CAST(:notificationId AS bigint)
            AND employee_id = CAST(:userId AS bigint)`,
        { notificationId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'NOTIFICATION_NOT_FOUND', '본인 알림이 아니거나 없는 알림입니다.');
      }
      await db.execute(
        `DELETE FROM notification
          WHERE notification_id = CAST(:notificationId AS bigint)
            AND employee_id = CAST(:userId AS bigint)`,
        { notificationId, userId: user.id },
      );
      await db.execute(
        `INSERT INTO change_history
           (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at)
         VALUES
           ('notification', CAST(:notificationId AS bigint), '삭제', now(), CAST(:userId AS bigint), :beforeContent, NULL, now(), now())`,
        { notificationId, userId: user.id, beforeContent: String(rows[0]['title']) },
      );
      return {};
    });
  }

  @Get('/messages')
  async listMessages(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const messageType = text(query['messageType']);
    const attachmentTitle = text(query['attachmentTitle']);
    const userName = text(query['userName']);
    if (messageType !== '' && !MESSAGE_TYPES.includes(messageType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '메시지 유형이 올바르지 않습니다.');
    }
    const pageText = text(query['page']);
    const sizeText = text(query['size']);
    const page = pageText === '' ? 0 : Number(pageText);
    const size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    return transaction(async (db) => {
      const where = `
        (m.sender_id = CAST(:userId AS bigint)
          OR EXISTS (SELECT 1 FROM message_recipient mr
                      WHERE mr.message_id = m.message_id
                        AND mr.recipient_id = CAST(:userId AS bigint)))
        AND (:messageType = '' OR m.message_type = :messageType)
        AND (:attachmentTitle = '' OR EXISTS (SELECT 1 FROM attachment a
                      WHERE a.owner_type = :ownerType
                        AND a.owner_id = m.message_id
                        AND a.file_name ILIKE '%' || :attachmentTitle || '%'))
        AND (:userName = '' OR s.name ILIKE '%' || :userName || '%'
          OR EXISTS (SELECT 1 FROM message_recipient mr2
                       JOIN employee re ON re.employee_id = mr2.recipient_id
                      WHERE mr2.message_id = m.message_id
                        AND re.name ILIKE '%' || :userName || '%'))`;
      const params = {
        userId: user.id,
        messageType,
        attachmentTitle,
        userName,
        ownerType: MESSAGE_OWNER_TYPE,
      };
      const items = await db.query(
        `SELECT m.message_id AS "messageId",
                m.message_type AS "messageType",
                m.subject AS "subject",
                m.content AS "content",
                m.sent_at AS "sentAt",
                s.name AS "senderName"
           FROM message m
           JOIN employee s ON s.employee_id = m.sender_id
          WHERE ${where}
          ORDER BY m.sent_at DESC NULLS LAST, m.message_id DESC
          LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)`,
        { ...params, limit: String(limit), offset: String(page * limit) },
      );
      const totals = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM message m
           JOIN employee s ON s.employee_id = m.sender_id
          WHERE ${where}`,
        params,
      );
      return { items, page, size: limit, total: Number(totals[0]['total']) };
    });
  }

  @Delete('/messages/:messageId')
  @HttpCode(200)
  async deleteMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const messageId = req.params['messageId'];
    if (!/^[0-9]+$/.test(messageId)) {
      throw new ApiError(404, 'MESSAGE_NOT_FOUND', '메시지를 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT m.sender_id AS "senderId",
                m.message_type AS "messageType",
                m.subject AS "subject",
                (m.sender_id = CAST(:userId AS bigint)) AS "isSender"
           FROM message m
          WHERE m.message_id = CAST(:messageId AS bigint)
            AND (m.sender_id = CAST(:userId AS bigint)
              OR EXISTS (SELECT 1 FROM message_recipient mr
                          WHERE mr.message_id = m.message_id
                            AND mr.recipient_id = CAST(:userId AS bigint)))`,
        { messageId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MESSAGE_NOT_FOUND', '본인 메시지가 아니거나 없는 메시지입니다.');
      }
      if (rows[0]['isSender'] === true) {
        // 가정: 발신자가 삭제하면 메시지 자체를 지우고, 수신자만 삭제하면 본인 수신 행만 지운다.
        await db.execute(
          `UPDATE message SET reply_to_message_id = NULL, updated_at = now()
            WHERE reply_to_message_id = CAST(:messageId AS bigint)`,
          { messageId },
        );
        await db.execute(
          `UPDATE message SET forward_from_message_id = NULL, updated_at = now()
            WHERE forward_from_message_id = CAST(:messageId AS bigint)`,
          { messageId },
        );
        await db.execute(
          `DELETE FROM message_recipient WHERE message_id = CAST(:messageId AS bigint)`,
          { messageId },
        );
        await db.execute(
          `DELETE FROM message WHERE message_id = CAST(:messageId AS bigint)`,
          { messageId },
        );
      } else {
        await db.execute(
          `DELETE FROM message_recipient
            WHERE message_id = CAST(:messageId AS bigint)
              AND recipient_id = CAST(:userId AS bigint)`,
          { messageId, userId: user.id },
        );
      }
      await db.execute(
        `INSERT INTO change_history
           (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at)
         VALUES
           ('message', CAST(:messageId AS bigint), '삭제', now(), CAST(:userId AS bigint), :beforeContent, NULL, now(), now())`,
        { messageId, userId: user.id, beforeContent: String(rows[0]['subject'] ?? rows[0]['messageType']) },
      );
      return {};
    });
  }
}

