import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Filters, Form, Pager, Pairs, Select, TextInput, Tiles, call, useData } from '../kit';
import type { PageProps, Page, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['NOTE', '쪽지'],
  ['CHAT', '대화'],
  ['MAIL', '메일'],
];

const NOTI_OPTIONS: [string, string][] = [
  ['ALERT', '알림'],
  ['MENTION', '멘션'],
];

export default function FnSfr03603Page({ role, notify }: PageProps) {
  const [notiDraft, setNotiDraft] = useState('');
  const [notiType, setNotiType] = useState('');
  const [notiPage, setNotiPage] = useState(0);
  const [draft, setDraft] = useState({ messageType: '', attachmentTitle: '', userName: '' });
  const [applied, setApplied] = useState({ messageType: '', attachmentTitle: '', userName: '' });
  const [msgPage, setMsgPage] = useState(0);
  const [message, setMessage] = useState<Row | null>(null);
  const [removeNoti, setRemoveNoti] = useState<Row | null>(null);

  const notis = useData<Page>(
    () => call<Page>('GET', '/notifications', role, undefined, { notificationType: notiType, page: notiPage, size: 10 }),
    [role, notiType, notiPage],
  );
  const msgs = useData<Page>(
    () => call<Page>('GET', '/messages', role, undefined, { ...applied, page: msgPage, size: 10 }),
    [role, applied, msgPage],
  );

  async function markRead(row: Row) {
    try {
      await call('POST', `/notifications/${row.notificationId}/read`, role, {});
      notify('알림을 확인 처리했습니다.');
      notis.reload();
    } catch (e) {
      notify(e instanceof Error ? e.message : '처리하지 못했습니다.');
    }
  }

  const notiRows = notis.data?.items ?? [];
  const msgRows = msgs.data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황</h2>
        <Tiles items={[
          ['알림 건수', notis.data?.total ?? 0],
          ['메시지 건수', msgs.data?.total ?? 0],
        ]} />
      </section>

      <section className="box span-12">
        <h2>알림 이력</h2>
        <Filters
          onSearch={() => { setNotiPage(0); setNotiType(notiDraft); }}
          onReset={() => { setNotiDraft(''); setNotiType(''); setNotiPage(0); }}
        >
          <Field label="알림 구분">
            <Select value={notiDraft} onChange={setNotiDraft} options={NOTI_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={notis.data?.total} />
        {notis.error ? <p>{notis.error}</p> : null}
        <DataTable
          rows={notiRows}
          empty="결과가 없습니다."
          columns={[
            { key: 'notificationType', label: '알림 구분', render: (r) => <Badge value={r.notificationType} /> },
            { key: 'title', label: '제목' },
            { key: 'summary', label: '요약' },
            { key: 'occurredAt', label: '이벤트 발생 일시', render: (r) => <DateText value={r.occurredAt} time /> },
            { key: 'readYn', label: '읽음 여부', render: (r) => (r.readYn ? '읽음' : '안 읽음') },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  {r.readYn ? null : <button type="button" onClick={() => markRead(r)}>확인</button>}
                  <button type="button" onClick={() => setRemoveNoti(r)}>삭제</button>
                </span>
              ),
            },
          ]}
        />
        <Pager page={notiPage} size={notis.data?.size ?? 10} total={notis.data?.total ?? 0} onPage={setNotiPage} />
      </section>

      <section className="box span-12">
        <h2>통합 메시지</h2>
        <Filters
          onSearch={() => { setMsgPage(0); setApplied(draft); }}
          onReset={() => {
            const empty = { messageType: '', attachmentTitle: '', userName: '' };
            setDraft(empty);
            setApplied(empty);
            setMsgPage(0);
          }}
        >
          <Field label="메시지 유형">
            <Select value={draft.messageType} onChange={(v) => setDraft({ ...draft, messageType: v })} options={TYPE_OPTIONS} placeholder="전체" />
          </Field>
          <Field label="파일명">
            <TextInput value={draft.attachmentTitle} onChange={(v) => setDraft({ ...draft, attachmentTitle: v })} />
          </Field>
          <Field label="성명">
            <TextInput value={draft.userName} onChange={(v) => setDraft({ ...draft, userName: v })} />
          </Field>
        </Filters>
        <Band total={msgs.data?.total} />
        {msgs.error ? <p>{msgs.error}</p> : null}
        <DataTable
          rows={msgRows}
          onRowClick={(r) => setMessage(r)}
          empty="결과가 없습니다."
          columns={[
            { key: 'messageType', label: '메시지 유형', render: (r) => <Badge value={r.messageType} /> },
            { key: 'subject', label: '제목' },
            { key: 'senderName', label: '성명' },
            { key: 'sentAt', label: '발송 일시', render: (r) => <DateText value={r.sentAt} time /> },
          ]}
        />
        <Pager page={msgPage} size={msgs.data?.size ?? 10} total={msgs.data?.total ?? 0} onPage={setMsgPage} />
      </section>

      {message ? (
        <Drawer title="메시지 상세" onClose={() => setMessage(null)}>
          <Pairs items={[
            ['메시지 유형', <Badge value={message.messageType} />],
            ['제목', String(message.subject ?? '')],
            ['성명', String(message.senderName ?? '')],
            ['발송 일시', <DateText value={message.sentAt} time />],
            ['메시지 내용', String(message.content ?? '')],
          ]} />
          <Form
            submit="삭제"
            danger
            note="삭제한 메시지는 되돌릴 수 없습니다."
            onSubmit={async () => {
              await call('DELETE', `/messages/${message.messageId}`, role);
              notify('메시지를 삭제했습니다.');
              setMessage(null);
              msgs.reload();
            }}
          />
        </Drawer>
      ) : null}

      {removeNoti ? (
        <Drawer title="알림 삭제" onClose={() => setRemoveNoti(null)}>
          <Pairs items={[
            ['제목', String(removeNoti.title ?? '')],
            ['요약', String(removeNoti.summary ?? '')],
            ['이벤트 발생 일시', <DateText value={removeNoti.occurredAt} time />],
          ]} />
          <Form
            submit="삭제"
            danger
            note="삭제한 알림은 되돌릴 수 없습니다."
            onSubmit={async () => {
              await call('DELETE', `/notifications/${removeNoti.notificationId}`, role);
              notify('알림을 삭제했습니다.');
              setRemoveNoti(null);
              notis.reload();
            }}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
